'use strict';

/**
* Convert an array of symbol aliases and/or shorthands to canonical symbol aliases.
*
* @module @stdlib/plot/base/symbols2aliases
*
* @example
* var symbols2aliases = require( '@stdlib/plot/base/symbols2aliases' );
*
* var v = symbols2aliases( [ 'o', 's' ] );
* // returns [ 'circle', 'square' ]
*
* v = symbols2aliases( [ 'o', 'beep' ] );
* // returns [ 'circle', null ]
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
